{"HelperA.dfy": "if |s| == 0 {
      A.Empty(s);
      assert s + t == t;
      A.Empty(s);
    } else {
      O1.Unfold(s + t);
      assert (s + t)[0] == s[0];
      assert (s + t)[1..] == s[1..] + t;
      Prove(s[1..], t);
      O1.Unfold(s);
      O2.Snoc(K.Rev(t) + K.Rev(s[1..]), s[0]);
      O2.Snoc(K.Rev(s[1..]), s[0]);
    }"}

